<?php require __DIR__.'/app/bootstrap.php';$title='Categories';$categories=all("SELECT c.*,(SELECT COUNT(*) FROM menu_items m JOIN seller_applications s ON s.user_id=m.seller_id WHERE m.category_id=c.id AND ".live_sql('m')." AND s.status='approved') live_count FROM categories c WHERE c.active=1 ORDER BY c.name",[]);require ROOT.'/app/header.php'; ?>
<main class="page shell" id="main"><div class="page-heading"><span class="heading-kicker">WHAT ARE YOU CRAVING?</span><h1>A flavor for every mood.</h1><p>Find something delicious in categories curated by our team.</p></div><div class="category-cards"><?php foreach($categories as $c): ?><a class="category-tile" href="<?=e(url('index.php?category='.$c['id']))?>"><span class="category-tile-icon" aria-hidden="true"><?=category_ui_icon($c['name'],40)?></span><h2><?=e($c['name'])?></h2><p><?=$c['live_count']?> available <?=$c['live_count']==1?'dish':'dishes'?></p><b>Explore →</b></a><?php endforeach ?></div><?php if(!$categories): ?><p class="panel empty">Fresh categories are coming soon.</p><?php endif ?></main><?php require ROOT.'/app/footer.php'; ?>
